contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 reqID, bool repayDirect, bool isCallback) public {
        require(reqID < 100);
        bool reverted;
        uint256 loanID;
        uint256 lid = c.clearRequest(reqID, repayDirect, isCallback); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
            loanID = lid;
        }
        assert(reverted || (!reverted && loanID == 0));
    }
    receive() external payable {}
}

