// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 reqID, bool repayDirect, bool isCallback) internal {
        reqID = bound(reqID, 0, 99);
        bool reverted;
        uint256 loanID;
        try c.clearRequest(reqID, repayDirect, isCallback) returns (uint256 lid) {
            reverted = false;
            loanID = lid;
        } catch {
            reverted = true;
        }
        assertTrue(reverted || (!reverted && loanID == 0));
    }

    function testFuzz_run(uint256 reqID, bool repayDirect, bool isCallback) public {
        _run(reqID, repayDirect, isCallback);
    }

    receive() external payable {}
}
